nan Perbaikan Tanggul dan Penggantian Pintu Air',NULL,NULL,'Menunggu',NULL,'2026-08-05 08:25:22','2026-08-05 08:25:22'),(237,NULL,'2026-08-05','427/LH.12.06','Kel. Kelapa Gading Barat',NULL,NULL,NULL,NULL,NULL,NULL,'Pengurasan Saluran Kali Gendong Jl. Yos Sudarso (turunan flyover Artha Gading)',NULL,NULL,'Menunggu',NULL,'2026-08-05 08:25:22','2026-08-05 08:25:22'),(238,NULL,'2026-08-05','747/LH.01.03','Kel. Rorotan',NULL,NULL,NULL,NULL,NULL,NULL,'Permohonan Pengurasan Saluran di Jl. Karang Tengah RT 008 RW 008 Kel. Rorotan',NULL,NULL,'Menunggu',NULL,'2026-08-05 08:25:22','2026-08-05 08:25:22'),(239,NULL,'2026-08-05','320/KR.01.01','Kelurahan Tugu Selatan',NULL,NULL,NULL,NULL,NULL,NULL,'Permohonan Pengerukan Sedimen Lumpur di RT 008 RW 05 Kel. Tugu Selatan',NULL,NULL,'Menunggu',NULL,'2026-08-05 08:25:22','2026-08-05 08:25:22'),(240,NULL,'2026-08-05','148/06/10/2026','RT 006/10 Kel. Lagoa',NULL,NULL,NULL,NULL,NULL,NULL,'Permohonan Pengangkatan Lumpur dan Puing Bongkaran Perbaikan Saluran Air di Jl. Mangga Gang 3 RT 06 07 rw 10 Kel. Lagoa',NULL,NULL,'Menunggu',NULL,'2026-08-05 08:25:22','2026-08-05 08:25:22');
